    {
      "name": "MvPolynomial.coeff_rename_embDomain",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_4} [inst : CommSemiring R] (f : σ ↪ τ) (φ : MvPolynomial σ R) (d : σ →₀ ℕ),\n  MvPolynomial.coeff (Finsupp.embDomain f d) ((MvPolynomial.rename ⇑f) φ) = MvPolynomial.coeff d φ"
    },
    {
      "name": "MvPolynomial.coeff_rename_mapDomain",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_4} [inst : CommSemiring R] (f : σ → τ),\n  Function.Injective f →\n    ∀ (φ : MvPolynomial σ R) (d : σ →₀ ℕ),\n      MvPolynomial.coeff (Finsupp.mapDomain f d) ((MvPolynomial.rename f) φ) = MvPolynomial.coeff d φ"
    },
    {
      "name": "MvPolynomial.coeff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → (σ →₀ ℕ) → MvPolynomial σ R → R"
    },
    {
      "name": "MvPowerSeries.coeff",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_2} → [inst : Semiring R] → (σ →₀ ℕ) → MvPowerSeries σ R →ₗ[R] R"
    },
    {
      "name": "MvPolynomial.constantCoeff_rename",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_4} [inst : CommSemiring R] {τ : Type u_6} (f : σ → τ) (φ : MvPolynomial σ R),\n  MvPolynomial.constantCoeff ((MvPolynomial.rename f) φ) = MvPolynomial.constantCoeff φ"
    }
  ]
}

