    {
      "name": "Polynomial.coeff_C_mul_X",
      "type": " {R : Type u} [Semiring R] (x : R) (n : ℕ) : (Polynomial.C x * Polynomial.X).coeff n = if n = 1 then x else 0",
      "module": "Mathlib.Algebra.Polynomial.Coeff"
    },
    {
      "name": "Polynomial.coeff_C_mul",
      "type": " {R : Type u} {a : R} {n : ℕ} [Semiring R] (p : Polynomial R) : (Polynomial.C a * p).coeff n = a * p.coeff n",
      "module": "Mathlib.Algebra.Polynomial.Coeff"
    },
    {
      "name": "Polynomial.coeff_mul_C",
      "type": " {R : Type u} [Semiring R] (p : Polynomial R) (n : ℕ) (a : R) : (p * Polynomial.C a).coeff n = p.coeff n * a",
      "module": "Mathlib.Algebra.Polynomial.Coeff"
    },
    {
      "name": "Polynomial.coeff_C_mul_X_pow",
      "type": " {R : Type u} [Semiring R] (x : R) (k n : ℕ) : (Polynomial.C x * Polynomial.X ^ k).coeff n = if n = k then x else 0",
      "module": "Mathlib.Algebra.Polynomial.Coeff"
    },
    {
      "name": "Polynomial.coeff_X_add_C_pow",
      "type": " {R : Type u} [Semiring R] (r : R) (n k : ℕ) : ((Polynomial.X + Polynomial.C r) ^ n).coeff k = r ^ (n - k) * ↑(n.choose k)",
      "module": "Mathlib.Algebra.Polynomial.Coeff"
    },
    {
      "name": "Polynomial.update_eq_add_sub_coeff",
      "type": " {R : Type u_1} [Ring R] (p : Polynomial R) (n : ℕ) (a : R) : p.update n a = p + Polynomial.C (a - p.coeff n) * Polynomial.X ^ n",
      "module": "Mathlib.Algebra.Polynomial.Coeff"
    }
  ]
}

