    {
      "name": "Poly.mul_apply",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (f g : Poly α) (x : α → ℕ), (f * g) x = f x * g x"
    },
    {
      "name": "MvPolynomial.coeff_mul",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : DecidableEq σ] (p q : MvPolynomial σ R) (n : σ →₀ ℕ),\n  MvPolynomial.coeff n (p * q) = ∑ x ∈ Finset.antidiagonal n, MvPolynomial.coeff x.1 p * MvPolynomial.coeff x.2 q"
    },
    {
      "name": "Polynomial.coeff_mul",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p q : Polynomial R) (n : ℕ),\n  (p * q).coeff n = ∑ x ∈ Finset.antidiagonal n, p.coeff x.1 * q.coeff x.2"
    },
    {
      "name": "MonomialOrder.coeff_mul_of_add_of_degree_le",
      "module_name": "Mathlib.RingTheory.MvPolynomial.MonomialOrder",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {m : MonomialOrder σ} {R : Type u_2} [inst : CommSemiring R] {f g : MvPolynomial σ R} {a b : σ →₀ ℕ},\n  m.toSyn (m.degree f) ≤ m.toSyn a →\n    m.toSyn (m.degree g) ≤ m.toSyn b →\n      MvPolynomial.coeff (a + b) (f * g) = MvPolynomial.coeff a f * MvPolynomial.coeff b g"
    },
    {
      "name": "Polynomial.leadingCoeff_prod",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {R : Type u} {ι : Type w} (s : Finset ι) [inst : CommSemiring R] [NoZeroDivisors R] (f : ι → Polynomial R),\n  (∏ i ∈ s, f i).leadingCoeff = ∏ i ∈ s, (f i).leadingCoeff"
    },
    {
      "name": "Polynomial.leadingCoeff_multiset_prod",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] [NoZeroDivisors R] (t : Multiset (Polynomial R)),\n  t.prod.leadingCoeff = (Multiset.map (fun f => f.leadingCoeff) t).prod"
    }
  ]
}

